#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────


# ghcr 이미지 배포로 옮기기 전에 사람이 해야 하는 일(2026-09-17 설계).
# 이 개발 머신(sub2)에서 돌린다 — gh CLI 와 `ssh sub`, sub 를 거친 `ssh oracle` 을 쓴다.
# 2026-10-15(#705) 이미지가 GitHub Actions 에서 Jenkins 로 옮겨 mac 러너·저장소 변수·Jenkins API 토큰 단계를 뺐다.
# 2026-10-15(#711) 앱의 공개 값이 실행 env 로 옮겨 codemit-images-env 자격증명 단계를 뺐다 — 값은 서버의 .env.<target> 에만 있다.

cd "$(dirname "$0")/.."
REPO="sandcorporation/laurio"
STAGING_ENV="/server/jenkins/workspace/codemit-deploy-staging/docker/.env.staging"   # sub 호스트
PROD_ENV="/var/jenkins_home/workspace/codemit-deploy-prod/docker/.env.prod"       # oracle 호스트
# 다시 돌릴 때의 기본값 — 저장소 밖에 둔다(비밀값이 섞인다).
ENV_FILE="${HOME}/.config/codemit-ghcr-wizard.env"
mkdir -p "$(dirname "$ENV_FILE")"; touch "$ENV_FILE"; chmod 600 "$ENV_FILE"

_ssh_noise='post-quantum|store now|upgraded'
# on_sub / on_oracle: 표준입력의 bash 스크립트를 그 호스트에서 돈다. 값은 명령줄이
# 아니라 스크립트 본문(표준입력)으로 넘어가 ps 에 드러나지 않는다.
on_sub()    { ssh sub 'bash -s' 2> >(grep -vE "$_ssh_noise" >&2); }
on_oracle() { ssh sub 'timeout 120 ssh -o BatchMode=yes oracle "bash -s"' 2> >(grep -vE "$_ssh_noise" >&2); }

TOTAL_STAGES=4

banner "Codemit — ghcr 이미지 배포 준비 (사람 작업)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "사전 확인"
say "gh 권한과 두 서버 접속, env 파일 둘을 확인합니다."
gh auth status >/dev/null 2>&1 || { warn "gh 로그인이 필요합니다: gh auth login"; exit 1; }
[[ "$(gh api "repos/$REPO" --jq .permissions.admin)" == "true" ]] || { warn "$REPO 관리자 권한이 필요합니다"; exit 1; }
printf 'sudo -n test -f %q && stat -c "%%a" %q\n' "$STAGING_ENV" "$STAGING_ENV" | on_sub | sed 's/^/  sub   .env.staging 권한: /' \
  || { warn "sub 에 접속하지 못했거나 $STAGING_ENV 가 없습니다(sudo 필요)"; exit 1; }
printf 'sudo -n test -f %q && sudo -n stat -c "%%a" %q\n' "$PROD_ENV" "$PROD_ENV" | on_oracle | sed 's/^/  oracle .env.prod 권한: /' \
  || { warn "oracle 에 접속하지 못했거나 $PROD_ENV 가 없습니다(sudo 필요)"; exit 1; }
warn ".env.staging 은 비밀값 파일인데 누구나 읽을 수 있는(644) 상태였습니다(2026-09-17 확인)."
if confirm "sub 의 .env.staging 권한을 600 으로 바꿀까요? (Jenkins 는 root 로 돌아 영향 없음)"; then
  printf 'sudo chmod 600 %q && stat -c "  → %%a" %q\n' "$STAGING_ENV" "$STAGING_ENV" | on_sub
fi
pause "계속하려면 Enter"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "ghcr pull 토큰 발급"
say "staging·prod 서버가 비공개 이미지를 받을 때 쓸 읽기 전용 토큰입니다."
say "ghcr 는 SSH 키로 로그인할 수 없고, classic PAT 가 필요합니다."
open_url "https://github.com/settings/tokens/new?scopes=read:packages&description=codemit-ghcr-pull"
step "Note: codemit-ghcr-pull (미리 채워져 있음)"
step "Expiration: 원하는 기간 (만료되면 배포가 pull 에서 멈춥니다 — 달력에 적어 두세요)"
step "Select scopes: read:packages 만 체크되어 있는지 확인 → Generate token → 복사"
GHCR_USER=$(gh api user --jq .login)
note "토큰 주인: ${GHCR_USER} (sandcorporation 패키지를 읽을 수 있는 계정이어야 합니다)"
ask_secret GHCR_READ_TOKEN "토큰을 붙여 넣으세요 (ghp_...):"
[[ "$GHCR_READ_TOKEN" == ghp_* ]] || warn "classic PAT 는 보통 ghp_ 로 시작합니다 — 다시 확인하세요"
write_env GHCR_USER "$GHCR_USER"
write_env GHCR_READ_TOKEN "$GHCR_READ_TOKEN"   # 다시 돌릴 때의 기본값(저장소 밖, 600)

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "두 배포 에이전트에 ghcr 로그인 저장"
say "sub 의 jenkins, oracle 의 jenkins-desktop-agent 컨테이너 안에서 한 번 로그인해 둡니다."
note "두 컨테이너 모두 /root/.docker 가 named volume 이라 컨테이너를 다시 만들어도 로그인이 남습니다."
note "deploy.sh 는 배포 때 이 로그인으로 받고, 없으면 preflight 에서 멈춥니다."
if confirm "두 컨테이너에서 ${GHCR_USER} 로 ghcr.io 에 로그인할까요?"; then
  # 토큰은 원격 스크립트 본문(표준입력)으로만 넘어가고, 컨테이너 안에서도 --password-stdin 이다.
  login_in() {
    printf 'printf %%s %q | docker exec -i %q docker login ghcr.io -u %q --password-stdin >/dev/null && docker exec %q sh -c %q && echo %q\n' \
      "$GHCR_READ_TOKEN" "$1" "$GHCR_USER" "$1" 'grep -q "\"ghcr.io\"" /root/.docker/config.json' "  ✓ $1: ghcr 로그인이 /root/.docker 에 저장됐다"
  }
  login_in jenkins | on_sub || { warn "sub jenkins 컨테이너에서 로그인하지 못했습니다"; SKIPPED+=("sub jenkins ghcr 로그인"); }
  login_in jenkins-desktop-agent | on_oracle || { warn "oracle 에이전트 컨테이너에서 로그인하지 못했습니다"; SKIPPED+=("oracle 에이전트 ghcr 로그인"); }
  warn "docker 가 토큰을 /root/.docker/config.json 에 평문(base64)으로 저장합니다 — 두 볼륨을 백업할 때 그 사실을 기억하세요."
else
  SKIPPED+=("두 에이전트의 ghcr 로그인")
fi
pause "계속하려면 Enter"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "ghcr push 토큰 → Jenkins 자격증명 ghcr-push-token"
say "이미지는 Jenkins 잡 codemit-deploy-staging 이 굽고 올립니다(#705 — macos 가 arm64, sub 가 amd64). 쓰기 토큰이 필요합니다."
open_url "https://github.com/settings/tokens/new?scopes=write:packages&description=codemit-ghcr-push"
step "Select scopes: write:packages(read:packages 가 따라 붙습니다) → Generate token → 복사"
step "Jenkins → Manage Jenkins → Credentials → (global) → Add Credentials"
step "Kind: Secret text · ID: ghcr-push-token · Secret: 방금 복사한 토큰"
[[ -n "${JENKINS_UI_URL:-$(_existing JENKINS_UI_URL)}" ]] && open_url "$(_existing JENKINS_UI_URL)/manage/credentials/store/system/domain/_/newCredentials"
note "토큰은 이 위저드가 저장하지 않습니다 — Jenkins 에만 둡니다."
pause "만들었으면 Enter"

finish
note "위저드 기본값 파일: $ENV_FILE (비밀값 포함, 권한 600) — 다 끝나면 지워도 됩니다."
